package ez.minar.system.menu.components.settings; import ez.minar.system.settings.Setting; import ez.minar.system.settings.impl.KeybindSetting; import ez.minar.utils.helpers.KeyHelper; import net.minecraft.client.gui.DrawContext; public class KeybindSettingRenderer implements SettingRenderer<KeybindSetting> { @Override public boolean supports(Setting setting) { return setting instanceof KeybindSetting; } @Override public void render(DrawContext context, KeybindSetting setting, SettingRendererContext rendererContext, float x, float y, float width, float scale, float opacity) { rendererContext.renderRow(context, setting, getValue(setting), x, y, width, scale, opacity); } @Override public boolean click(KeybindSetting setting, SettingRendererContext rendererContext, int button, float localX, float localY, float width) { return button == 0; } @Override public float getHeight(KeybindSetting setting, SettingRendererContext rendererContext) { return SettingRendererContext.SETTING_HEIGHT; } @Override public String getValue(KeybindSetting setting) { return setting.getKeybind() < 0 ? "Press key..." : KeyHelper.getKeyName(setting.getKeybind()); } }